questionvariables.text:
stack_include("contribl://prooflib.mac");
proof_steps: [
 ["intro", "Let \\(p\\) be a prime number with \\(p \\gt 3\\)."],
 ["dots",  "Then \\(p^2 - 1 = (p - 1)(p + 1)\\)."],
 ["odd",   "Since \\(p\\) is a prime greater than 2, \\(p\\) is odd, so \\(p - 1\\) and \\(p + 1\\) are consecutive even numbers."],
 ["eight", "Of two consecutive even numbers, one is a multiple of 4 and the other is a multiple of 2, so \\((p - 1)(p + 1)\\) is a multiple of \\(4 \\times 2 = 8\\)."],
 ["three", "Of the three consecutive integers \\(p - 1\\), \\(p\\), \\(p + 1\\), exactly one is a multiple of 3."],
 ["notp",  "Since \\(p\\) is a prime greater than 3, \\(p\\) is not a multiple of 3. So \\(p - 1\\) or \\(p + 1\\) is a multiple of 3, and \\((p - 1)(p + 1)\\) is a multiple of 3."],
 ["conc",  "So \\(p^2 - 1\\) is a multiple of 8 and a multiple of 3. Since 8 and 3 have no common factor other than 1, \\(p^2 - 1\\) is a multiple of \\(8 \\times 3 = 24\\)."],
 ["dboth", "Two consecutive even numbers are both multiples of 4, so \\((p - 1)(p + 1)\\) is a multiple of \\(4 \\times 4 = 16\\)."],
 ["drule", "So \\(p^2 - 1\\) is a multiple of 8 and a multiple of 3. A number that is a multiple of two numbers is always a multiple of their product, so \\(p^2 - 1\\) is a multiple of 24."]
];
proof_steps: random_permutation(proof_steps);
/* Dependency graph: every path is a chain of steps that must come in this order.
   The factor-8 and factor-3 modules commute; the factorisation can come anywhere before the conclusion.
   dboth and drule are logically wrong blocks and are in no path. */
tdag: [["intro", "odd", "eight", "conc"], ["intro", "three", "notp", "conc"], ["intro", "dots", "conc"]];
ta: proof("intro", "dots", "odd", "eight", "three", "notp", "conc");

feedbackvariables.text:
sa: parsons_decode(ans1);
saprob: proof_assessment_dag(sa, tdag);
usedkeys: args(sa);
useddboth: member("dboth", usedkeys);
useddrule: member("drule", usedkeys);
usedwrong: useddboth or useddrule;
missk: listify(apply(union, cons({}, map(lambda([ex], first(args(ex))), sublist(saprob, lambda([ex], safe_op(ex) = "proof_step_missing"))))));
mustp: map(args, sublist(saprob, lambda([ex], safe_op(ex) = "proof_step_must")));
